import { useState } from 'react'
import { View } from 'tamagui'
import { type VideoProps, VideoFallback, defaultVideoLabels } from './shared'

/**
 * A video with the platform's own controls: `<video>` on web, the player
 * registered with `setVideoView` on iOS and Android.
 */
export function Video({
  src,
  title,
  poster,
  captions = [],
  ratio = 16 / 9,
  autoPlay = false,
  muted = autoPlay,
  loop = false,
  controls = true,
  onEnded,
  onError,
  labels,
  ...props
}: VideoProps) {
  const [failed, setFailed] = useState(false)
  return (
    <View
      width="100%"
      aspectRatio={ratio}
      borderRadius="$lg"
      overflow="hidden"
      backgroundColor="$muted"
      {...props}
    >
      {failed ? (
        <VideoFallback message={labels?.error ?? defaultVideoLabels.error} />
      ) : (
        <video
          src={typeof src === 'string' ? src : undefined}
          poster={poster}
          aria-label={title}
          controls={controls}
          autoPlay={autoPlay}
          muted={muted}
          loop={loop}
          // iOS Safari otherwise jumps to full screen on play.
          playsInline
          preload="metadata"
          onEnded={onEnded}
          onError={() => {
            setFailed(true)
            onError?.()
          }}
          style={{ display: 'block', width: '100%', height: '100%', objectFit: 'contain' }}
        >
          {captions.map((track) => (
            <track
              key={track.src}
              kind={track.kind ?? 'captions'}
              src={track.src}
              srcLang={track.srcLang}
              label={track.label}
              default={track.default}
            />
          ))}
        </video>
      )}
    </View>
  )
}

import { useEffect, useState } from 'react'
import { View } from 'tamagui'
import { type VideoProps, VideoFallback, defaultVideoLabels, getVideoView } from './shared'

let warned = false

/**
 * A video with the platform's own controls: `<video>` on web, the player
 * registered with `setVideoView` on iOS and Android.
 */
export function Video({
  src,
  title,
  poster: _poster,
  captions: _captions,
  ratio = 16 / 9,
  autoPlay = false,
  muted = autoPlay,
  loop = false,
  controls = true,
  onEnded,
  onError,
  labels,
  ...props
}: VideoProps) {
  const Player = getVideoView()
  const [failed, setFailed] = useState(false)
  // A missing player is a setup mistake; say so once instead of showing a blank box.
  useEffect(() => {
    if (Player || warned) return
    warned = true
    console.warn(
      'Video: no native player. Call setVideoView() at app start (e.g. with expo-video).',
    )
  }, [Player])

  return (
    <View
      width="100%"
      aspectRatio={ratio}
      borderRadius="$lg"
      overflow="hidden"
      backgroundColor="$muted"
      {...props}
    >
      {Player && !failed ? (
        <Player
          source={src}
          autoPlay={autoPlay}
          muted={muted}
          loop={loop}
          controls={controls}
          accessibilityLabel={title}
          onEnded={onEnded}
          onError={() => {
            setFailed(true)
            onError?.()
          }}
          style={{ width: '100%', height: '100%' }}
        />
      ) : (
        <VideoFallback message={labels?.error ?? defaultVideoLabels.error} />
      )}
    </View>
  )
}

import { AlertCircleIcon } from '@advui/icons'
import type { ComponentType } from 'react'
import { type GetProps, View } from 'tamagui'
import { Text } from '../typography/Text'

export interface VideoCaptionTrack {
  /** A WebVTT file. */
  src: string
  /** Language code, e.g. `en` or `my`. */
  srcLang: string
  /** Shown in the player's captions menu, e.g. "English". */
  label: string
  /** `captions` (default) include sounds; `subtitles` only speech. */
  kind?: 'captions' | 'subtitles'
  default?: boolean
}

export interface VideoLabels {
  /** Shown when the video cannot be played. */
  error: string
}

export const defaultVideoLabels: VideoLabels = {
  error: 'This video can’t be played.',
}

export interface VideoProps extends Omit<GetProps<typeof View>, 'children'> {
  /** A URL, or `require()` of a bundled file on native. */
  src: string | number
  /** Names the video for screen readers. Say what it shows. */
  title: string
  /** Image shown before playback (web). */
  poster?: string
  /** Caption or subtitle tracks (web). */
  captions?: VideoCaptionTrack[]
  /** Width / height. Default: 16 / 9. */
  ratio?: number
  /** Starts muted: browsers block autoplay with sound. */
  autoPlay?: boolean
  /** Default: `autoPlay`. */
  muted?: boolean
  loop?: boolean
  /** The platform's playback controls. Default: true. */
  controls?: boolean
  onEnded?: () => void
  onError?: () => void
  labels?: Partial<VideoLabels>
}

/** What the app's native player receives; see `setVideoView`. */
export interface NativeVideoViewProps {
  source: string | number
  autoPlay: boolean
  muted: boolean
  loop: boolean
  controls: boolean
  accessibilityLabel: string
  onEnded?: () => void
  onError?: () => void
  style: { width: '100%'; height: '100%' }
}

// A module value (not context) so it also reaches videos inside native portals.
let appVideoView: ComponentType<NativeVideoViewProps> | undefined

/**
 * Registers the app's native video player for every Video, e.g. a small
 * wrapper around `expo-video`. Web needs none: it uses `<video>`.
 */
export function setVideoView(view: ComponentType<NativeVideoViewProps> | undefined) {
  appVideoView = view
}

export function getVideoView() {
  return appVideoView
}

/** Shown in place of the video when it fails, or when native has no player. */
export function VideoFallback({ message }: { message: string }) {
  return (
    <View flex={1} alignItems="center" justifyContent="center" gap="$2" padding="$4">
      <View aria-hidden>
        <AlertCircleIcon size={24} color="$mutedForeground" />
      </View>
      <Text size="sm" tone="muted" textAlign="center">
        {message}
      </Text>
    </View>
  )
}

